"use client";

import { useEffect, useState } from 'react';
import { useClerk } from '@clerk/nextjs';
import { motion } from 'framer-motion';
import Image from 'next/image';

/**
 * Dedicated sign-out page that handles the sign-out process
 * This avoids React hooks errors by having a dedicated page for sign-out
 */
export default function SignOutPage() {
  const clerk = useClerk();
  const [status, setStatus] = useState('Signing you out...');
  const [error, setError] = useState(null);
  const [progress, setProgress] = useState(0);

  useEffect(() => {
    // Function to handle sign-out
    const performSignOut = async () => {
      try {
        // Start progress animation
        const progressInterval = setInterval(() => {
          setProgress(prev => {
            if (prev >= 100) {
              clearInterval(progressInterval);
              return 100;
            }
            return prev + 5;
          });
        }, 100);

        // Sign out the user
        await clerk.signOut();
        setStatus('Sign out successful! Redirecting...');

        // Ensure progress reaches 100%
        setProgress(100);

        // Redirect to home page after a short delay
        setTimeout(() => {
          // Use window.location.replace for a cleaner transition
          // This avoids React hook errors by completely unmounting all components
          window.location.replace('/');
        }, 1000);

        return () => clearInterval(progressInterval);
      } catch (err) {
        console.error('Error during sign-out:', err);
        setError('There was an error signing you out. Redirecting to home page...');
        setProgress(100);

        // Redirect to home page even if there's an error
        setTimeout(() => {
          window.location.replace('/');
        }, 2000);
      }
    };

    // Start the sign-out process
    performSignOut();
  }, [clerk]);

  return (
    <div className="min-h-screen flex flex-col items-center justify-center bg-gray-900">
      <div className="flex flex-col items-center max-w-md w-full px-4">
        {/* Logo */}
        <motion.div
          className="mb-8 relative w-20 h-20"
          initial={{ scale: 0.8, opacity: 0 }}
          animate={{ scale: 1, opacity: 1 }}
          transition={{ duration: 0.5 }}
        >
          <Image
            src="/Logo.PNG"
            alt="OratorPath Logo"
            fill
            className="object-contain filter brightness-125 contrast-125"
            priority
          />
        </motion.div>

        {/* Status message */}
        <motion.h1
          className="text-2xl font-bold text-white mb-2 text-center"
          initial={{ y: 20, opacity: 0 }}
          animate={{ y: 0, opacity: 1 }}
          transition={{ delay: 0.2, duration: 0.5 }}
        >
          {error ? 'Sign Out Error' : 'Signing Out'}
        </motion.h1>

        <motion.p
          className="text-gray-300 mb-8 text-center"
          initial={{ y: 20, opacity: 0 }}
          animate={{ y: 0, opacity: 1 }}
          transition={{ delay: 0.3, duration: 0.5 }}
        >
          {error || status}
        </motion.p>

        {/* Progress bar */}
        <motion.div
          className="w-full bg-gray-800 rounded-full h-2.5 mb-6 overflow-hidden"
          initial={{ width: "80%", opacity: 0 }}
          animate={{ width: "100%", opacity: 1 }}
          transition={{ delay: 0.4, duration: 0.5 }}
        >
          <motion.div
            className="bg-gradient-to-r from-purple-500 to-pink-500 h-2.5 rounded-full"
            initial={{ width: "0%" }}
            animate={{ width: `${progress}%` }}
            transition={{ duration: 0.8, ease: "easeInOut" }}
          />
        </motion.div>

        {/* Subtle hint */}
        <motion.p
          className="text-gray-500 text-sm text-center"
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: 0.5, duration: 0.5 }}
        >
          You will be redirected automatically
        </motion.p>
      </div>
    </div>
  );
}
